        INSERT INTO presensi (
            sesi_id,
            siswa_id,
            status,
            keterangan
        )

        SELECT
            new_sesi.id,
            presensi_data.siswa_id,
            presensi_data.status,
            presensi_data.keterangan

        FROM new_sesi

        CROSS JOIN (
            VALUES ${values.join(",")}
        ) AS presensi_data(
            siswa_id,
            status,
            keterangan
        )

        RETURNING
            id,
