QUERY REKAP
====================================================

Rekap:

1. Guru yang sedang login
2. Kelas yang dipilih
3. Tahun ajaran yang dipilih
4. Rentang tanggal yang dipilih

Setiap siswa hanya muncul SATU BARIS.

Jika guru memiliki beberapa mata pelajaran
di kelas yang sama, seluruh presensinya
digabungkan.

====================================================
*/

msg.query = `

SELECT

    kelas.id AS kelas_id,

    kelas.nama_kelas,

    kelas.tingkat,

    kelas.jurusan,

    kelas.tahun_ajaran,

    guru.id AS guru_id,

    guru.nama_lengkap AS nama_guru,

    siswa.id AS siswa_id,

    siswa.nis,

    siswa.nisn,

    siswa.nama_lengkap,

    siswa.jenis_kelamin,


    /*
    ================================================
    JUMLAH PERTEMUAN
    ================================================
    */

    COUNT(
        DISTINCT sesi.id
    ) AS jumlah_pertemuan,


    /*
    ================================================
    HADIR
    ================================================
    */

    COUNT(presensi.id)
        FILTER (
            WHERE presensi.status = 'hadir'
        ) AS jumlah_hadir,


    /*
    ================================================
    SAKIT
    ================================================
    */

    COUNT(presensi.id)
        FILTER (
            WHERE presensi.status = 'sakit'
        ) AS jumlah_sakit,


    /*
    ================================================
    IZIN
    ================================================
    */

    COUNT(presensi.id)
        FILTER (
            WHERE presensi.status = 'izin'
        ) AS jumlah_izin,


    /*
    ================================================
    TANPA KETERANGAN
    ================================================
    */

    COUNT(presensi.id)
        FILTER (
            WHERE presensi.status = 'tanpa_keterangan'
        ) AS jumlah_tanpa_keterangan,


    /*
    ================================================
    TOTAL PRESENSI
    ================================================
    */

    COUNT(presensi.id)
        AS jumlah_presensi


FROM guru_mapel


/*
====================================================
GURU
====================================================
*/

JOIN guru

    ON guru_mapel.guru_id =
       guru.id


/*
====================================================
USER LOGIN
====================================================
*/

JOIN users

    ON guru.user_id =
       users.id


/*
====================================================
KELAS
====================================================
*/

JOIN kelas

    ON guru_mapel.kelas_id =
       kelas.id


/*
====================================================
SISWA
====================================================
*/

JOIN siswa

    ON siswa.kelas_id =
       kelas.id

   AND siswa.status = 'aktif'


/*
====================================================
SESI
====================================================

Ambil semua sesi guru pada kelas tersebut
dalam rentang tanggal.

====================================================
*/

LEFT JOIN sesi

    ON sesi.guru_mapel_id =
       guru_mapel.id

   AND sesi.status = 'selesai'

   AND sesi.tanggal >= $3::date

   AND sesi.tanggal <= $4::date


/*
====================================================
PRESENSI
====================================================
*/

LEFT JOIN presensi

    ON presensi.sesi_id =
       sesi.id

   AND presensi.siswa_id =
       siswa.id


/*
====================================================
FILTER
====================================================
*/

WHERE users.id = $1

  AND guru_mapel.kelas_id = $2

  AND guru_mapel.tahun_ajaran = $5

  AND guru_mapel.status = 'aktif'

  AND kelas.status = 'aktif'


/*
====================================================
GROUP PER SISWA
====================================================
*/

GROUP BY

    kelas.id,

    kelas.nama_kelas,

    kelas.tingkat,

    kelas.jurusan,

    kelas.tahun_ajaran,

    guru.id,

    guru.nama_lengkap,

    siswa.id,

    siswa.nis,

    siswa.nisn,

    siswa.nama_lengkap,

    siswa.jenis_kelamin


/*
====================================================
URUTKAN
====================================================
*/

ORDER BY

    siswa.nama_lengkap;

`;


/*
====================================================
PARAMETER POSTGRESQL
====================================================
*/

msg.params = [

    Number(userId),

    Number(kelasId),

    tanggalMulai,

    tanggalSelesai,

    tahunAjaran

];


return msg;

const hasil = msg.payload;

msg.headers = {
    "Content-Type":
        "application/json; charset=utf-8"
};


if (!Array.isArray(hasil)) {

    msg.statusCode = 500;

    msg.payload = {
        success: false,
        message:
            "Format hasil database tidak valid."
    };

    return msg;
}


msg.statusCode = 200;

msg.payload = {

    success: true,

    data: hasil

};


return msg;

/*
 * =========================================================
 * FUNCTION TELEGRAM
 * Notifikasi presensi siswa
 * =========================================================
 */

let hasil = msg.payload;


/*
 * =========================================================
 * NORMALISASI DATA
 * =========================================================
 */

if (!Array.isArray(hasil)) {

    if (hasil && Array.isArray(hasil.rows)) {
        hasil = hasil.rows;
    } else {
        hasil = [];
    }

}


/*
 * Kalau tidak ada data
 */
if (hasil.length === 0) {
    return null;
}


/*
 * =========================================================
 * AMBIL DATA DARI BARIS PERTAMA
 * =========================================================
 */

const first = hasil[0];


/*
 * Beberapa kemungkinan nama field
 * supaya aman terhadap output PostgreSQL
 */

const namaGuru =
    first.nama_guru ||
    first.guru_nama ||
    first.nama_lengkap_guru ||
    "-";


const namaMapel =
    first.nama_mapel ||
    first.mata_pelajaran ||
    first.nama_mata_pelajaran ||
    "-";


const namaKelas =
    first.nama_kelas ||
    first.kelas_nama ||
    "-";


const tanggal =
    first.tanggal ||
    first.tanggal_presensi ||
    "-";


/*
 * =========================================================
 * NORMALISASI STATUS
 * =========================================================
 */

function getStatus(row) {

    return (
        row.status_presensi ||
        row.presensi_status ||
        row.status ||
        ""
    ).toString().toLowerCase().trim();

}


/*
 * =========================================================
 * NORMALISASI NAMA SISWA
 * =========================================================
 */

function getNamaSiswa(row) {

    return (
        row.nama_siswa ||
        row.nama_lengkap ||
        row.siswa_nama ||
        row.nama ||
        "Nama siswa tidak ditemukan"
    );

}


/*
 * =========================================================
 * NORMALISASI KETERANGAN
 * =========================================================
 */

function getKeterangan(row) {

    return (
        row.keterangan ||
        ""
    ).toString().trim();

}


/*
 * =========================================================
 * HITUNG STATUS
 * =========================================================
 */

const siswaHadir = hasil.filter(row =>
    getStatus(row) === "hadir"
);


const siswaSakit = hasil.filter(row =>
    getStatus(row) === "sakit"
);


const siswaIzin = hasil.filter(row =>
    getStatus(row) === "izin"
);


const siswaTanpaKeterangan = hasil.filter(row =>
    getStatus(row) === "tanpa_keterangan"
);


/*
 * =========================================================
 * FORMAT TANGGAL
 * =========================================================
 */

let tanggalFormat = tanggal;

try {

    const d = new Date(tanggal);

    if (!isNaN(d.getTime())) {

        tanggalFormat = d.toLocaleDateString(
            "id-ID",
            {
                day: "2-digit",
                month: "long",
                year: "numeric"
            }
        );

    }

} catch (error) {

    tanggalFormat = tanggal;

}


/*
 * =========================================================
 * BUAT PESAN
 * =========================================================
 */

let pesan = "";

pesan += "🔔 NOTIFIKASI PRESENSI\n\n";

pesan += "🏫 Kelas: " + namaKelas + "\n";
pesan += "📚 Mata Pelajaran: " + namaMapel + "\n";
pesan += "👨‍🏫 Guru: " + namaGuru + "\n";
pesan += "📅 Tanggal: " + tanggalFormat + "\n\n";


/*
 * =========================================================
 * REKAP
 * =========================================================
 */

pesan += "📊 REKAP KEHADIRAN\n\n";

pesan += "✅ Hadir: " + siswaHadir.length + "\n";

pesan += "🤒 Sakit: " + siswaSakit.length + "\n";

pesan += "📄 Izin: " + siswaIzin.length + "\n";

pesan +=
    "❌ Tanpa Keterangan: " +
    siswaTanpaKeterangan.length +
    "\n";


/*
 * =========================================================
 * DAFTAR SISWA SAKIT
 * =========================================================
 */

if (siswaSakit.length > 0) {

    pesan += "\n🤒 DAFTAR SISWA SAKIT\n";

    siswaSakit.forEach(row => {

        pesan +=
            "• " +
            getNamaSiswa(row);

        const keterangan =
            getKeterangan(row);

        if (keterangan) {

            pesan +=
                " — " +
                keterangan;

        }

        pesan += "\n";

    });

}


/*
 * =========================================================
 * DAFTAR SISWA IZIN
 * =========================================================
 */

if (siswaIzin.length > 0) {

    pesan += "\n📄 DAFTAR SISWA IZIN\n";

    siswaIzin.forEach(row => {

        pesan +=
            "• " +
            getNamaSiswa(row);

        const keterangan =
            getKeterangan(row);

        if (keterangan) {

            pesan +=
                " — " +
                keterangan;

        }

        pesan += "\n";

    });

}


/*
 * =========================================================
 * DAFTAR SISWA TANPA KETERANGAN
 * =========================================================
 */

if (siswaTanpaKeterangan.length > 0) {

    pesan +=
        "\n❌ DAFTAR SISWA TANPA KETERANGAN\n";

    siswaTanpaKeterangan.forEach(row => {

        pesan +=
            "• " +
            getNamaSiswa(row);

        const keterangan =
            getKeterangan(row);

        if (keterangan) {

            pesan +=
                " — " +
                keterangan;

        }

        pesan += "\n";

    });

}


/*
 * =========================================================
 * DATA UNTUK TELEGRAM SENDER
 * =========================================================
 */

msg.payload = {

    chatId: -4129309784,

    type: "message",

    content: pesan

};


return msg;
